120	    }
121	
122	    fn next_token(&mut self, context: Self::LexContext) -> Self::Kind {
123	        self.current_start = self.text_position();
124	        self.current_flags = TokenFlags::empty();
125	
126	        let kind = match self.current_byte() {
127	            Some(current) => self.consume_token(current, context),
128	            None => EOF,
129	        };
130	
131	        self.current_flags
132	            .set(TokenFlags::PRECEDING_LINE_BREAK, self.after_newline);
