164	/// Restore virtual line start to saved value.
165	fn restore_virtual_line_start_if_needed(
166	    p: &mut MarkdownParser,
167	    saved_virtual: Option<Option<biome_rowan::TextSize>>,
168	) {
169	    if let Some(prev) = saved_virtual {
170	        p.state_mut().virtual_line_start = prev;
171	    }
172	}
